import{_ as e,o as i,c as o,a5 as t}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 62 话 MPA 级转场：View Transitions + Speculation Rules","description":"","frontmatter":{},"headers":[],"relativePath":"comics/scenarios/EP.62-mpa-view-transitions.md","filePath":"comics/scenarios/EP.62-mpa-view-transitions.md","lastUpdated":1793853676000}'),r={name:"comics/scenarios/EP.62-mpa-view-transitions.md"};function s(n,a,l,c,d,h){return i(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="漫画-·-第-62-话-mpa-级转场-view-transitions-speculation-rules" tabindex="-1">漫画 · 第 62 话 MPA 级转场：View Transitions + Speculation Rules <a class="header-anchor" href="#漫画-·-第-62-话-mpa-级转场-view-transitions-speculation-rules" aria-label="Permalink to &quot;漫画 · 第 62 话 MPA 级转场：View Transitions + Speculation Rules&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/scenarios/03-mpa-view-transitions">docs/scenarios/03-mpa-view-transitions.md</a> ｜ 原画：<a href="./EP.62-mpa-view-transitions.svg">EP.62-mpa-view-transitions.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。本话她把内容站从 SPA 迁回 MPA，首屏快了，但每次点链接都白屏闪一下。</li><li><strong>标签君</strong>：结构师。负责把“视觉连续”和“文档预取”拆成两层渐进增强。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>迁回 MPA 后，首屏加载从 2.4s 降到 0.9s，可页面切换像回到十年前：旧页瞬间消失，新页白屏后再出现。像素酱想装回 SPA，标签君拦住她：跨文档 View Transitions 可以让 MPA 也有形变，Speculation Rules 可以提前准备下一页。两层都不支持时，普通导航仍然可用。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>传统 MPA 导航有两次空档：离开旧页的瞬间没有过渡，新页首帧之前没有内容。用户感知为“闪白”。加载动画只能遮住第二次空档，遮不住第一次的结构断裂。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>@view-transition { navigation: auto }</code> 让浏览器在导航时对旧页截图、按 <code>view-transition-name</code> 提取元素，再与新页同名元素插值。名字必须全页唯一且新旧页都存在，否则退化为淡入淡出。Speculation Rules 用 JSON 声明 <code>prefetch</code> 或 <code>prerender</code>，<code>eagerness</code> 控制触发时机；预取把网络等待提前到用户犹豫时。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>像素酱给头部、文章封面、标题设唯一名字；列表页对文章链接加 <code>prerender</code>，<code>eagerness: moderate</code>；保留原加载态作为不支持浏览器的兜底；<code>prefers-reduced-motion</code> 下缩短形变。支持转场的浏览器跨页切换连续，预取命中时导航 200ms 内完成，不支持的环境仍是普通 MPA。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li><code>view-transition-name</code> 必须唯一且稳定，重复命名会让整组动画失效。</li><li>给大量元素命名会生成大量截图与伪元素，合成开销明显。</li><li>预取不是越多越好：<code>eagerness</code> 越高命中率越高，也越费流量与 CPU。</li><li>两项能力都是渐进增强，基础导航必须首先可用。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：给列表页所有卡片都设 <code>view-transition-name: card</code>，为什么转场反而不动了？</p><p><strong>答</strong>：<code>view-transition-name</code> 在同一页面必须唯一。多元素同名会让浏览器无法确定哪个旧元素对应哪个新元素，整组转场被放弃。应按数据 ID 生成唯一名字，如 <code>card-${id}</code>，并只为需要形变的少量元素命名，避免合成开销。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>点击卡片观察封面与标题的形变，返回列表观察反向插值：<a href="./../../examples/scenarios/03-mpa-view-transitions">examples/scenarios/03-mpa-view-transitions</a></li><li>模拟预取命中与未命中，对比日志中的导航耗时说明。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>场景篇收官。第 63 话起进入架构篇：《设计令牌的分层与落地》——把颜色、间距、字体变成可治理的契约。</p>',22)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
